1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.LocalityResolver;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
23	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(formatMembershipTier(owner))")
26	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
27	    @Mapping(target = "sharesHousehold", ignore = true)
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * Builds an owner's display name from the stored names, formatted as
32	     * {@code "LastName, FirstName"}.
33	     */
34	    default String formatDisplayName(Owner owner) {
35	        return owner.getLastName() + ", " + owner.getFirstName();
36	    }
37	
38	    /**
39	     * Builds an owner's initials from the stored names as the upper-cased first
40	     * letters of the first and last name, dot-separated with a trailing dot,
41	     * e.g. {@code "J.S."}.
42	     */
43	    default String formatInitials(Owner owner) {
44	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
45	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
46	    }
47	
48	    /**
49	     * Builds an owner's membership number from its stored fields, formatted
50	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of
51	     * the registration date's year, e.g. {@code "SMI-0007-M26"}. Returns
52	     * {@code null} when either the customer code or registration date is absent.
53	     */
54	    default String formatMembershipNumber(Owner owner) {
55	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
56	            return null;
57	        }
58	        return String.format("%s-M%02d", owner.getCustomerCode(),
59	            owner.getRegistrationDate().getYear() % 100);
60	    }
61	
62	    /**
63	     * Determines an owner's membership tier from its stored fields: {@code "SILVER"} when
64	     * the owner has no namesakes (a {@code namesakeCount} of 0) and an email is present,
65	     * otherwise {@code "BRONZE"}.
66	     */
67	    default String formatMembershipTier(Owner owner) {
68	        boolean noNamesakes = Integer.valueOf(0).equals(owner.getNamesakeCount());
69	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
70	        return noNamesakes && hasEmail ? "SILVER" : "BRONZE";
71	    }
72	
73	    /**
74	     * Derives an owner's locality (canonical region) from its stored city using the
75	     * fixed city-to-region table, yielding {@code "UNKNOWN"} for any unlisted city.
76	     */
77	    default String formatLocality(Owner owner) {
78	        return LocalityResolver.localityOf(owner.getCity());
79	    }
80	
81	    Owner toOwner(OwnerDto ownerDto);
82	
83	    @Mapping(target = "id", ignore = true)
84	    @Mapping(target = "pets", ignore = true)
85	    @Mapping(target = "householdId", ignore = true)
86	    Owner toOwner(OwnerFieldsDto ownerDto);
87	
88	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
89	
90	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
91	
92	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
93	        OwnerPageDto ownerPageDto = new OwnerPageDto();
94	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
95	        ownerPageDto.setPage(ownerPage.getNumber());
96	        ownerPageDto.setSize(ownerPage.getSize());
97	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
98	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
99	        return ownerPageDto;
100	    }
101	}
