31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.BulkSignupWarningEvaluator;
33	import org.springframework.samples.petclinic.rest.CustomerCodeGenerator;
34	import org.springframework.samples.petclinic.rest.NamesakeCounter;
35	import org.springframework.samples.petclinic.rest.OwnerAuditLogger;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.CityOwnerLimitException;
45	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitException;
46	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
47	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
48	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
49	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
50	import org.springframework.samples.petclinic.rest.validation.HouseholdIdGenerator;
51	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
52	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
53	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
54	import org.springframework.samples.petclinic.service.ClinicService;
55	import org.springframework.samples.petclinic.util.BusinessDayResolver;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    private final OwnerFieldsValidator ownerFieldsValidator;
82	
83	    private final HouseholdDuplicateValidator householdDuplicateValidator;
84	
85	    private final HouseholdIdGenerator householdIdGenerator;
86	
87	    private final TelephoneNormalizer telephoneNormalizer;
88	
89	    private final EmailNormalizer emailNormalizer;
90	
91	    private final AddressNormalizer addressNormalizer;
92	
93	    private final CustomerCodeGenerator customerCodeGenerator;
94	
95	    private final NamesakeCounter namesakeCounter;
96	
97	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
98	
99	    private final OwnerAuditLogger ownerAuditLogger;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper,
105	                                 OwnerFieldsValidator ownerFieldsValidator,
106	                                 HouseholdDuplicateValidator householdDuplicateValidator,
107	                                 HouseholdIdGenerator householdIdGenerator,
108	                                 TelephoneNormalizer telephoneNormalizer,
109	                                 EmailNormalizer emailNormalizer,
110	                                 AddressNormalizer addressNormalizer,
111	                                 CustomerCodeGenerator customerCodeGenerator,
112	                                 NamesakeCounter namesakeCounter,
113	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
114	                                 OwnerAuditLogger ownerAuditLogger) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	        this.ownerFieldsValidator = ownerFieldsValidator;
120	        this.householdDuplicateValidator = householdDuplicateValidator;
121	        this.householdIdGenerator = householdIdGenerator;
122	        this.telephoneNormalizer = telephoneNormalizer;
123	        this.emailNormalizer = emailNormalizer;
124	        this.addressNormalizer = addressNormalizer;
125	        this.customerCodeGenerator = customerCodeGenerator;
126	        this.namesakeCounter = namesakeCounter;
127	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
128	        this.ownerAuditLogger = ownerAuditLogger;
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
134	        Collection<Owner> owners;
135	        if (lastName != null) {
136	            owners = this.clinicService.findOwnerByLastName(lastName);
137	        } else {
138	            owners = this.clinicService.findAllOwners();
139	        }
140	        if (owners.isEmpty()) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
159	        if (ownerFieldsDto != null) {
160	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
161	        }
162	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
163	        if (!missingFields.isEmpty()) {
164	            throw new MissingOwnerFieldsException(missingFields);
165	        }
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        Collection<Owner> sameLastName =
169	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
170	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
171	        applyHouseholdPolicy(owner, ownerFieldsDto, sameLastName);
172	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
173	        if (!this.clinicService.findOwnersByTelephone(normalizedTelephone).isEmpty()) {
174	            throw new DuplicateTelephoneException(normalizedTelephone);
175	        }
176	        owner.setTelephone(normalizedTelephone);
177	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
178	        if (owner.getRegistrationDate() == null) {
179	            owner.setRegistrationDate(LocalDate.now());
180	        }
181	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
182	        LocalDate registrationDate = owner.getRegistrationDate();
183	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
184	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
185	            throw new DailyOwnerLimitException(registrationDate);
186	        }
187	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
188	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
189	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
190	            throw new CityOwnerLimitException(owner.getCity());
191	        }
192	        owner.setCustomerCode(customerCodeGenerator.generate(
193	            owner.getCity(), owner.getLastName(), cityOwnerCount));
194	        this.clinicService.saveOwner(owner);
195	        ownerAuditLogger.ownerCreated(owner);
196	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
197	        headers.setLocation(UriComponentsBuilder.newInstance()
198	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
199	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
200	    }
201	
202	    /**
203	     * Applies the household rule to an owner about to be created. When the owner shares a
204	     * household (same last name and address, compared case-insensitively with collapsed
205	     * whitespace) with an existing owner, creation is rejected unless the request opted in via
206	     * {@code sharesHousehold}. When it opts in, the new owner and every existing household
207	     * member are stamped with the same stable {@code householdId}.
208	     *
209	     * @throws DuplicateHouseholdException if a conflicting owner exists and the caller did not opt in
210	     */
211	    private void applyHouseholdPolicy(Owner owner, OwnerFieldsDto ownerFieldsDto, Collection<Owner> sameLastName) {
212	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
213	        if (members.isEmpty()) {
214	            return;
215	        }
216	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
217	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
218	        }
219	        String householdId = householdIdGenerator.generate(owner);
220	        owner.setHouseholdId(householdId);
221	        for (Owner member : members) {
222	            if (!householdId.equals(member.getHouseholdId())) {
223	                member.setHouseholdId(householdId);
224	                this.clinicService.saveOwner(member);
225	            }
226	        }
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner == null) {
234	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	        }
236	        currentOwner.setAddress(ownerFieldsDto.getAddress());
237	        currentOwner.setCity(ownerFieldsDto.getCity());
238	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
239	        currentOwner.setLastName(ownerFieldsDto.getLastName());
240	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
241	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
242	        this.clinicService.saveOwner(currentOwner);
243	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
244	    }
245	
246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Transactional
248	    @Override
249	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
250	        Owner owner = this.clinicService.findOwnerById(ownerId);
251	        if (owner == null) {
252	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
253	        }
254	        this.clinicService.deleteOwner(owner);
255	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
256	    }
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
261	        Owner owner = this.clinicService.findOwnerById(ownerId);
262	        if (owner == null) {
263	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	        }
265	        HttpHeaders headers = new HttpHeaders();
266	        Pet pet = petMapper.toPet(petFieldsDto);
267	        owner.setId(ownerId);
268	        pet.setOwner(owner);
269	        pet.getType().setName(null);
270	        this.clinicService.savePet(pet);
271	        PetDto petDto = petMapper.toPetDto(pet);
272	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
273	            .buildAndExpand(pet.getId()).toUri());
274	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
275	    }
276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Override
279	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
280	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
281	        if (currentOwner != null) {
282	            Pet currentPet = this.clinicService.findPetById(petId);
283	            if (currentPet != null) {
284	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
285	                currentPet.setName(petFieldsDto.getName());
286	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
287	                this.clinicService.savePet(currentPet);
288	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
289	            }
290	        }
291	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
292	    }
293	
294	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
295	    @Override
296	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
297	        HttpHeaders headers = new HttpHeaders();
298	        Visit visit = visitMapper.toVisit(visitFieldsDto);
299	        Pet pet = new Pet();
300	        pet.setId(petId);
301	        visit.setPet(pet);
302	        this.clinicService.saveVisit(visit);
303	        VisitDto visitDto = visitMapper.toVisitDto(visit);
304	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
305	            .buildAndExpand(visit.getId()).toUri());
306	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
307	    }
308	
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Override
312	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
313	        Owner owner = this.clinicService.findOwnerById(ownerId);
314	        if (owner != null) {
315	            Pet pet = owner.getPet(petId);
316	            if (pet != null) {
317	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
318	            }
319	        }
320	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
321	    }
322	}
