61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    private final OwnerFieldsValidator ownerFieldsValidator;
82	
83	    private final HouseholdDuplicateValidator householdDuplicateValidator;
84	
85	    private final HouseholdIdGenerator householdIdGenerator;
86	
87	    private final TelephoneNormalizer telephoneNormalizer;
88	
89	    private final EmailNormalizer emailNormalizer;
90	
91	    private final AddressNormalizer addressNormalizer;
92	
93	    private final CustomerCodeGenerator customerCodeGenerator;
94	
95	    private final NamesakeCounter namesakeCounter;
96	
97	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
98	
99	    private final OwnerAuditLogger ownerAuditLogger;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper,
105	                                 OwnerFieldsValidator ownerFieldsValidator,
106	                                 HouseholdDuplicateValidator householdDuplicateValidator,
107	                                 HouseholdIdGenerator householdIdGenerator,
108	                                 TelephoneNormalizer telephoneNormalizer,
109	                                 EmailNormalizer emailNormalizer,
110	                                 AddressNormalizer addressNormalizer,
111	                                 CustomerCodeGenerator customerCodeGenerator,
112	                                 NamesakeCounter namesakeCounter,
113	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
114	                                 OwnerAuditLogger ownerAuditLogger) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	        this.ownerFieldsValidator = ownerFieldsValidator;
120	        this.householdDuplicateValidator = householdDuplicateValidator;
121	        this.householdIdGenerator = householdIdGenerator;
122	        this.telephoneNormalizer = telephoneNormalizer;
123	        this.emailNormalizer = emailNormalizer;
124	        this.addressNormalizer = addressNormalizer;
125	        this.customerCodeGenerator = customerCodeGenerator;
126	        this.namesakeCounter = namesakeCounter;
127	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
128	        this.ownerAuditLogger = ownerAuditLogger;
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
134	        Collection<Owner> owners;
135	        if (lastName != null) {
136	            owners = this.clinicService.findOwnerByLastName(lastName);
137	        } else {
138	            owners = this.clinicService.findAllOwners();
139	        }
140	        if (owners.isEmpty()) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
159	        if (ownerFieldsDto != null) {
160	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
161	        }
162	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
163	        if (!missingFields.isEmpty()) {
164	            throw new MissingOwnerFieldsException(missingFields);
165	        }
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        Collection<Owner> sameLastName =
169	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
170	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
171	        applyHouseholdPolicy(owner, ownerFieldsDto, sameLastName);
172	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
173	        if (!this.clinicService.findOwnersByTelephone(normalizedTelephone).isEmpty()) {
174	            throw new DuplicateTelephoneException(normalizedTelephone);
175	        }
176	        owner.setTelephone(normalizedTelephone);
177	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
178	        if (owner.getRegistrationDate() == null) {
179	            owner.setRegistrationDate(LocalDate.now());
180	        }
181	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
182	        LocalDate registrationDate = owner.getRegistrationDate();
183	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
184	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
185	            throw new DailyOwnerLimitException(registrationDate);
186	        }
187	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
188	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
189	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
190	            throw new CityOwnerLimitException(owner.getCity());
191	        }
192	        owner.setCustomerCode(customerCodeGenerator.generate(
193	            owner.getCity(), owner.getLastName(), cityOwnerCount));
194	        this.clinicService.saveOwner(owner);
195	        ownerAuditLogger.ownerCreated(owner);
196	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
197	        headers.setLocation(UriComponentsBuilder.newInstance()
198	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
199	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
200	    }
201	
202	    /**
203	     * Applies the household rule to an owner about to be created. When the owner shares a
204	     * household (same last name and address, compared case-insensitively with collapsed
