73	    /**
74	     * Derives an owner's locality (canonical region) from its stored city using the
75	     * fixed city-to-region table, yielding {@code "UNKNOWN"} for any unlisted city.
76	     */
77	    default String formatLocality(Owner owner) {
78	        return LocalityResolver.localityOf(owner.getCity());
79	    }
