25	/**
26	 * Decides whether a would-be owner shares a household with an existing one, i.e. has the
27	 * same last name and address. Household identity is delegated to {@link HouseholdKey}, so the
28	 * comparison ignores case and whitespace differences.
29	 */
30	@Component
31	public class HouseholdDuplicateValidator {
32	
33	    private final HouseholdKey householdKey;
34	
35	    public HouseholdDuplicateValidator(HouseholdKey householdKey) {
36	        this.householdKey = householdKey;
37	    }
38	
39	    /**
40	     * @param candidate the owner about to be created
41	     * @param existingOwners owners already stored (typically pre-filtered by last name)
42	     * @return the existing owners that belong to the same household as the candidate, in
43	     *         encounter order; empty when none do
44	     */
45	    public List<Owner> findHouseholdMembers(Owner candidate, Collection<Owner> existingOwners) {
46	        String key = householdKey.of(candidate);
47	        return existingOwners.stream()
48	            .filter(existing -> householdKey.of(existing).equals(key))
49	            .toList();
50	    }
51	
52	    /**
53	     * @param candidate the owner about to be created
54	     * @param existingOwners owners already stored (typically pre-filtered by last name)
55	     * @return {@code true} when any existing owner shares the candidate's household
56	     */
57	    public boolean sharesHouseholdWithExisting(Owner candidate, Collection<Owner> existingOwners) {
58	        return !findHouseholdMembers(candidate, existingOwners).isEmpty();
59	    }
60	}
